// UpdateAppJSONBody defines parameters for UpdateApp.
type UpdateAppJSONBody struct {
	// Amazon Amazon type details. Should only be used when type is amazon.
	Amazon *struct {
		// PackageName The package name of the app
		PackageName *string `json:"package_name,omitempty"`

		// SharedSecret Your Amazon Developer Identity Shared Key
		SharedSecret *string `json:"shared_secret,omitempty"`
	} `json:"amazon,omitempty"`

	// AppStore App Store type details. Should only be used when type is app_store.
	AppStore *struct {
		// AppStoreConnectAPIKey App Store Connect API Key downloaded from App Store Connect in PEM format. Copy the contents of the file in this field. This is optional and used for advanced features like product imports.
		AppStoreConnectAPIKey *string `json:"app_store_connect_api_key,omitempty"`

		// AppStoreConnectAPIKeyID App Store Connect API Key ID. The ID of the downloaded API key. You can get it from App Store Connect.
		AppStoreConnectAPIKeyID *string `json:"app_store_connect_api_key_id,omitempty"`

		// AppStoreConnectAPIKeyIssuer App Store Connect API Key Issuer ID.
		AppStoreConnectAPIKeyIssuer *string `json:"app_store_connect_api_key_issuer,omitempty"`

		// AppStoreConnectVendorNumber Your vendor number from App Store Connect. Required for some features like financial reports.
		AppStoreConnectVendorNumber *string `json:"app_store_connect_vendor_number,omitempty"`

		// BundleID The bundle ID of the app
		BundleID *string `json:"bundle_id,omitempty"`

		// SharedSecret The shared secret of the app
		SharedSecret *string `json:"shared_secret,omitempty"`

		// SubscriptionKeyID In App Key id. The ID of the downloaded in app key. You can get it from App Store Connect
		SubscriptionKeyID *string `json:"subscription_key_id,omitempty"`

		// SubscriptionKeyIssuer The key Issuer id. See instructions on how to obtain this in https://www.revenuecat.com/docs/in-app-purchase-key-configuration#3-providing-the-issuer-id-to-revenuecat
		SubscriptionKeyIssuer *string `json:"subscription_key_issuer,omitempty"`

		// SubscriptionPrivateKey PKCS
		SubscriptionPrivateKey *string `json:"subscription_private_key,omitempty"`
	} `json:"app_store,omitempty"`

	// MacAppStore Legacy Mac App Store type details. Should only be used when type is mac_app_store.
	MacAppStore *struct {
		// BundleID The bundle ID of the app
		BundleID *string `json:"bundle_id,omitempty"`

		// SharedSecret The shared secret of the app
		SharedSecret *string `json:"shared_secret,omitempty"`
	} `json:"mac_app_store,omitempty"`

	// Name The name of the app
	//
	// Example: My App
	Name *string `json:"name,omitempty"`

	// Paddle Paddle Billing type details. Should only be used when type is paddle.
	Paddle *struct {
		// PaddleAPIKey Paddle Server-side API key provided on the Paddle dashboard.
		PaddleAPIKey *string `json:"paddle_api_key,omitempty"`

		// PaddleIsSandbox Whether the app is tied to the sandbox environment.
		//
		// Example: true
		PaddleIsSandbox *bool `json:"paddle_is_sandbox,omitempty"`
	} `json:"paddle,omitempty"`

	// PlayStore Play Store type details. Should only be used when type is play_store.
	PlayStore *struct {
		// PackageName The package name of the app
		PackageName string `json:"package_name"`
	} `json:"play_store,omitempty"`

	// RcBilling Web Billing type details. Should only be used when type is rc_billing.
	RcBilling *struct {
		// AppName Shown in checkout, emails, and receipts sent to customers.
		AppName *string `json:"app_name,omitempty"`

		// DefaultCurrency ISO 4217 currency code
		//
		// Example: USD
		DefaultCurrency *RCBillingCurrency `json:"default_currency,omitempty"`

		// StripeAccountID It needs to be connected to your RevenueCat account. It can be omitted if you only have a single Stripe account connected to your RevenueCat account.
		StripeAccountID *string `json:"stripe_account_id,omitempty"`

		// SupportEmail Used as the `reply to` address in all emails sent to customers, to allow them to receive support. If you leave this field blank, your RevenueCat account email address will be used.
		SupportEmail *string `json:"support_email,omitempty"`
	} `json:"rc_billing,omitempty"`

	// Roku Roku Channel Store type details. Should only be used when type is roku.
	Roku *struct {
		// RokuAPIKey Roku Pay API key provided on the Roku Pay Web Services page.
		RokuAPIKey *string `json:"roku_api_key,omitempty"`

		// RokuChannelID Channel ID provided on the Roku Channel page.
		RokuChannelID *string `json:"roku_channel_id,omitempty"`

		// RokuChannelName Channel name that is displayed on the Roku Channel page.
		RokuChannelName *string `json:"roku_channel_name,omitempty"`
	} `json:"roku,omitempty"`

	// Stripe Stripe type details. Should only be used when type is stripe.
	Stripe *struct {
		// StripeAccountID It needs to be connected to your RevenueCat account. It can be omitted if you only have a single Stripe account connected to your RevenueCat account.
		StripeAccountID *string `json:"stripe_account_id,omitempty"`
	} `json:"stripe,omitempty"`
}

